// ─── Types & helpers ─────────────────────────────────────────────────────────

interface SearchResult {
  entry: NavEntry;
  parentName: string;
  snippet: string;
  matchCount: number;
}

const contentCache = new Map<string, string>();

async function fetchContent(file: string): Promise<string> {
  const cached = contentCache.get(file);
  if (cached !== undefined) return cached;
  try {
    const res = await fetch(`${__webpack_public_path__}content/${file}`);
    if (!res.ok) return '';
    const text = await res.text();
    contentCache.set(file, text);
    return text;
  } catch {
    contentCache.set(file, '');
    return '';
  }
}

function flattenWithParent(entries: NavEntry[], parent = ''): { entry: NavEntry; parentName: string }[] {
  return entries.flatMap((e) => {
    if (e.children) return flattenWithParent(e.children, e.name);
    if (e.file) return [{ entry: e, parentName: parent }];
    return [];
  });
}

function extractSnippet(text: string, query: string): { snippet: string; count: number } {
  const lower = text.toLowerCase();
  const q = query.toLowerCase();
  const lines = text.split('\n').filter(l => l.trim() && !l.startsWith('#') && !l.startsWith('|--') && !l.startsWith('```'));

  let count = 0;
  let idx = 0;
  while ((idx = lower.indexOf(q, idx)) !== -1) { count++; idx += q.length; }

  // Find best line with the match
  for (const line of lines) {
    const li = line.toLowerCase().indexOf(q);
    if (li === -1) continue;
    const clean = line.replace(/[#*_`|]/g, '').trim();
    const ci = clean.toLowerCase().indexOf(q);
    if (ci === -1) continue;
    const start = Math.max(0, ci - 40);
    const end = Math.min(clean.length, ci + q.length + 60);
    const prefix = start > 0 ? '…' : '';
    const suffix = end < clean.length ? '…' : '';
    const before = clean.slice(start, ci);
    const match = clean.slice(ci, ci + query.length);
    const after = clean.slice(ci + query.length, end);
    return { snippet: `${prefix}${before}<mark>${match}</mark>${after}${suffix}`, count };
  }
  return { snippet: '', count };
}

// ─── Component ───────────────────────────────────────────────────────────────

interface ContentSearchProps {
  entries: NavEntry[];
  activeId: string | null;
  onSelect: (entry: NavEntry) => void;
}

export function ContentSearch({ entries, activeId, onSelect }: ContentSearchProps) {
  const { collapsed } = useSidebar();
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<SearchResult[]>([]);
  const [searching, setSearching] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);
  const debounceRef = useRef<ReturnType<typeof setTimeout>>();

  const allLeaves = useMemo(() => flattenWithParent(entries), [entries]);

  const doSearch = useCallback(async (q: string) => {
    if (q.length < 2) { setResults([]); setSearching(false); return; }
    setSearching(true);

    const contents = await Promise.all(
      allLeaves.map(async ({ entry, parentName }) => {
        const text = await fetchContent(entry.file!);
        return { entry, parentName, text };
      })
    );

    const matches: SearchResult[] = [];
    for (const { entry, parentName, text } of contents) {
      const nameLower = entry.name.toLowerCase();
      const textLower = text.toLowerCase();
      const ql = q.toLowerCase();
      if (!nameLower.includes(ql) && !textLower.includes(ql)) continue;

      const { snippet, count } = extractSnippet(text, q);
      const nameMatch = nameLower.includes(ql);
      matches.push({
        entry,
        parentName,
        snippet: snippet || (nameMatch ? entry.name : ''),
        matchCount: count + (nameMatch ? 10 : 0),
      });
    }

    matches.sort((a, b) => b.matchCount - a.matchCount);
    setResults(matches);
    setSearching(false);
  }, [allLeaves]);

  useEffect(() => {
    clearTimeout(debounceRef.current);
    if (!query.trim()) { setResults([]); return; }
    debounceRef.current = setTimeout(() => doSearch(query.trim()), 300);
    return () => clearTimeout(debounceRef.current);
  }, [query, doSearch]);

  const isActive = query.length > 0;

  return (
    <>
      <Wrap collapsed={collapsed}>
        <SearchBox
          focused={isActive}
          collapsed={collapsed}
          onClick={() => inputRef.current?.focus()}
        >
          <Search size={13} color={isActive ? theme.colors.accent : theme.colors.sidebarTextMuted} style={{ flexShrink: 0 }} />
          <Input
            ref={inputRef}
            collapsed={collapsed}
            placeholder="Pesquisar conteúdo…"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
          />
          {isActive && !collapsed && (
            <ClearBtn onClick={() => { setQuery(''); setResults([]); }}>
              <X size={12} />
            </ClearBtn>
          )}
        </SearchBox>
      </Wrap>

      {isActive && !collapsed && (
        <Results>
          {searching && (
            <StatusText>
              <Spin><Loader2 size={13} /></Spin>
              A pesquisar…
            </StatusText>
          )}
          {!searching && results.length === 0 && query.length >= 2 && (
            <StatusText>Nenhum resultado para "{query}"</StatusText>
          )}
          {!searching && results.length > 0 && (
            <StatusText>
              <FileText size={13} />
              {results.length} {results.length === 1 ? 'resultado' : 'resultados'}
            </StatusText>
          )}
          {results.map((r) => (
            <ResultItem
              key={r.entry.id}
              active={activeId === r.entry.id}
              onClick={() => { onSelect(r.entry); setQuery(''); setResults([]); }}
            >
              <ResultTitle>
                {r.entry.name}
                <CountBadge>{r.matchCount > 10 ? r.matchCount - 10 : r.matchCount}×</CountBadge>
              </ResultTitle>
              {r.parentName && <ResultParent>{r.parentName}</ResultParent>}
              {r.snippet && <Snippet dangerouslySetInnerHTML={{ __html: r.snippet }} />}
            </ResultItem>
          ))}
        </Results>
      )}
    </>
  );
}

export default ContentSearch;
